(5714360, 831132, 65234, '<td valign="top">Yep, tells a story pretty effectively.  Off-beat and well done.</td>', 'Yep, tells a story pretty effectively.  Off-beat and well done.', '2009-11-04 17:16:48.000000', NULL, 1),
(5714364, 831456, 65234, '<td valign="top">Perfectly done!  The dog''s intent expression and the crystal-clear reflection of the person tells a wonderful story.</td>', 'Perfectly done!  The dog''s intent expression and the crystal-clear reflection of the person tells a wonderful story.', '2009-11-04 17:18:20.000000', NULL, 1),
(5714368, 831133, 65234, '<td valign="top">Definitely different.  That eel apparently doesn''t rely on camouflage!  Nice timing on the shot.  Kind of noisy but not more than I''d expect for a shot like this.</td>', 'Definitely different.  That eel apparently doesn''t rely on camouflage!  Nice timing on the shot.  Kind of noisy but not more than I''d expect for a shot like this.', '2009-11-04 17:21:05.000000', NULL, 1),
