(5715936, 831267, 102019, '<td valign="top">I may be slow, but I don''t see any animal interaction going on?</td>', 'I may be slow, but I don''t see any animal interaction going on?', '2009-11-05 23:13:15.000000', NULL, 1),
(5715937, 830860, 102019, '<td valign="top">Its a little dull, dark and has too much in the background.  I would have just cropped it at the goat and focused in on that beautiful smile.</td>', 'Its a little dull, dark and has too much in the background.  I would have just cropped it at the goat and focused in on that beautiful smile.', '2009-11-05 23:14:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5715938, 831456, 102019, '<td valign="top">I know what you were going for, but I needed more "action" in the interaction for this challenge...</td>', 'I know what you were going for, but I needed more "action" in the interaction for this challenge...', '2009-11-05 23:14:53.000000', NULL, 1),
(5715939, 830546, 102019, '<td valign="top">I asked the same question... Really?  why post an image so small...  I gave a score of 1, for not properly using the challenge dimensions.</td>', 'I asked the same question... Really?  why post an image so small...  I gave a score of 1, for not properly using the challenge dimensions.', '2009-11-05 23:15:19.000000', NULL, 1),
(5715940, 831242, 102019, '<td valign="top">Too dark, can''t see the subject, boring sunrise, too much of the image is dull and bland.</td>', 'Too dark, can''t see the subject, boring sunrise, too much of the image is dull and bland.', '2009-11-05 23:15:45.000000', NULL, 1),
(5715981, 831382, 3214, '<td valign="top">Looks as if the fish are observing the humans as well, works well for this challenge with the one human looking back at them. Super!</td>', 'Looks as if the fish are observing the humans as well, works well for this challenge with the one human looking back at them. Super!', '2009-11-06 00:24:04.000000', NULL, 1),
(5715982, 831250, 3214, '<td valign="top">Not crazy about your processing--too much noise reduction maybe?  But absolutely nuts over the moment you''ve captured, and I like the comp/square crop.</td>', 'Not crazy about your processing--too much noise reduction maybe?  But absolutely nuts over the moment you''ve captured, and I like the comp/square crop.', '2009-11-06 00:25:08.000000', NULL, 1),
(5715985, 831284, 3214, '<td valign="top">I like your little helper! This shot grows on me the longer I look at it.</td>', 'I like your little helper! This shot grows on me the longer I look at it.', '2009-11-06 00:27:56.000000', NULL, 1),
(5715986, 831117, 3214, '<td valign="top">It''s a neat shot but the star of this show should be the interaction, which is going on in the background. Not gonna hurt your score from me though, the originality rocks.</td>', 'It''s a neat shot but the star of this show should be the interaction, which is going on in the background. Not gonna hurt your score from me though, the originality rocks.', '2009-11-06 00:29:07.000000', NULL, 1),
(5715991, 831031, 3214, '<td valign="top">First rate, no vote, but I did want to comment.</td>', 'First rate, no vote, but I did want to comment.', '2009-11-06 00:35:03.000000', NULL, 1),
(5715992, 831411, 3214, '<td valign="top">Terrific, I know you wish you could vignette a little, but that''s basic-life! no vote.</td>', 'Terrific, I know you wish you could vignette a little, but that''s basic-life! no vote.', '2009-11-06 00:35:10.000000', NULL, 1),
(5716028, 830824, 37252, '<td valign="top">If it isn''t a PUG, it''s just a dog.   :)</td>', 'If it isn''t a PUG, it''s just a dog.   :)', '2009-11-06 03:04:56.000000', NULL, 1),
(5716086, 831438, 103069, '<td valign="top">Excellent photograph.  He looks like he is a lot of fun, and enjoying the play so much!  Great Capture, surely tells the story of interaction. 10</td>', 'Excellent photograph.  He looks like he is a lot of fun, and enjoying the play so much!  Great Capture, surely tells the story of interaction. 10', '2009-11-06 06:58:25.000000', NULL, 1),
(5716088, 831031, 103069, '<td valign="top">A very emotional photograph, catching a moment  Nicely done.  I have a farm, this photograph speaks loudly.</td>', 'A very emotional photograph, catching a moment  Nicely done.  I have a farm, this photograph speaks loudly.', '2009-11-06 06:59:28.000000', NULL, 1),
(5716089, 830974, 103069, '<td valign="top">Excellent photograph, living on a farm, this one really hits home.  Nice tones, and composition... Nicely done</td>', 'Excellent photograph, living on a farm, this one really hits home.  Nice tones, and composition... Nicely done', '2009-11-06 07:00:13.000000', NULL, 1),
(5716092, 830976, 103069, '<td valign="top">Great photograph, the only distraction is the post in front of the farmer.  If that had not been there then this would have been an EXCELLENT photo, but it is still very good!</td>', 'Great photograph, the only distraction is the post in front of the farmer.  If that had not been there then this would have been an EXCELLENT photo, but it is still very good!', '2009-11-06 07:01:08.000000', NULL, 1),
(5716095, 831221, 103069, '<td valign="top">A great shot, one of the special moments you were able to capture.  Wait till the the young one grows up and you can share this one with them.</td>', 'A great shot, one of the special moments you were able to capture.  Wait till the the young one grows up and you can share this one with them.', '2009-11-06 07:01:55.000000', NULL, 1),
(5716096, 831250, 103069, '<td valign="top">Your title and photograph are a perfect match.  Yes indeed the photograph tells me "BEST FREINDS"  great job.</td>', 'Your title and photograph are a perfect match.  Yes indeed the photograph tells me "BEST FREINDS"  great job.', '2009-11-06 07:02:28.000000', NULL, 1),
(5716097, 831393, 103069, '<td valign="top">This photograph makes me smile.  Very nicely done, great b/w tones.</td>', 'This photograph makes me smile.  Very nicely done, great b/w tones.', '2009-11-06 07:03:03.000000', NULL, 1),
(5716163, 831267, 65234, '<td valign="top">Pretty scene.  A bit unclear to me what sort of interaction is taking place, unless it''s the duck observing the people.  Can''t tell exactly what the people are doing, although I could guess fishing, since they appear to be on the water.  So could be several interactions, but not particularly emotive ones.</td>', 'Pretty scene.  A bit unclear to me what sort of interaction is taking place, unless it''s the duck observing the people.  Can''t tell exactly what the people are doing, although I could guess fishing, since they appear to be on the water.  So could be several interactions, but not particularly emotive ones.', '2009-11-06 08:53:58.000000', NULL, 1),
(5716167, 831131, 65234, '<td valign="top">Risky; those birds can be QUITE assertive!</td>', 'Risky; those birds can be QUITE assertive!', '2009-11-06 08:55:26.000000', NULL, 1),
(5716171, 830976, 65234, '<td valign="top">Oh, my.  They look hopeful in the back there, and the handfeeding undoubtedly builds trust ... and then I can''t help but wonder if these guys are trusting someone who will send them off to slaughter soon :-(  I find it disturbing.</td>', 'Oh, my.  They look hopeful in the back there, and the handfeeding undoubtedly builds trust ... and then I can''t help but wonder if these guys are trusting someone who will send them off to slaughter soon :-(  I find it disturbing.', '2009-11-06 08:58:20.000000', NULL, 1),
(5716173, 831199, 65234, '<td valign="top">Cute, but pushing the challenge concept.</td>', 'Cute, but pushing the challenge concept.', '2009-11-06 09:01:39.000000', NULL, 1),
(5716179, 831436, 65234, '<td valign="top">Like the contrast between the shaggy head and the groomed parts.  Cooperative little dog, though I''m guessing from the panting that s/he''s nervous (and I can understand that given where the groomer is headed with those clippers!).</td>', 'Like the contrast between the shaggy head and the groomed parts.  Cooperative little dog, though I''m guessing from the panting that s/he''s nervous (and I can understand that given where the groomer is headed with those clippers!).', '2009-11-06 09:03:57.000000', NULL, 1),
(5716181, 831312, 53200, '<td valign="top">How cute they are!  Would have rated higher if you had cropped tighter getting rid of the extraneous items on the left side.</td>', 'How cute they are!  Would have rated higher if you had cropped tighter getting rid of the extraneous items on the left side.', '2009-11-06 09:04:27.000000', NULL, 1),
(5716185, 830546, 65234, '<td valign="top">I''m sure I won''t be the only one to note that this is really small, which makes it hard to evaluate.</td>', 'I''m sure I won''t be the only one to note that this is really small, which makes it hard to evaluate.', '2009-11-06 09:05:39.000000', NULL, 1),
(5716187, 831389, 65234, '<td valign="top">Very sweet :-)  Looks like a Lensbaby-type effect, which works well here.</td>', 'Very sweet :-)  Looks like a Lensbaby-type effect, which works well here.', '2009-11-06 09:06:44.000000', NULL, 1),
(5716190, 830860, 65234, '<td valign="top">I see your shadow ;-)  Fun take on interaction.</td>', 'I see your shadow ;-)  Fun take on interaction.', '2009-11-06 09:07:51.000000', NULL, 1),
(5716194, 831438, 65234, '<td valign="top">Ack; snow already!!!  This tells a story in spades.  I fear if you were not using a long zoom that you may have been run over a split second after taking this ;-)</td>', 'Ack; snow already!!!  This tells a story in spades.  I fear if you were not using a long zoom that you may have been run over a split second after taking this ;-)', '2009-11-06 09:09:19.000000', NULL, 1),
(5716197, 831041, 65234, '<td valign="top">Consideraly worse than inconvenient for the deer, I imagine.  An all too common sight in these parts this time of year.</td>', 'Consideraly worse than inconvenient for the deer, I imagine.  An all too common sight in these parts this time of year.', '2009-11-06 09:10:56.000000', NULL, 1),
(5716201, 830454, 65234, '<td valign="top">Cute moment.  Lensbaby sort of effect works well, though I wish the little girl was a smidge farther into the focussed area and the sun on her face was a little less bright.  I do like her hair sticking up ;-)</td>', 'Cute moment.  Lensbaby sort of effect works well, though I wish the little girl was a smidge farther into the focussed area and the sun on her face was a little less bright.  I do like her hair sticking up ;-)', '2009-11-06 09:13:25.000000', NULL, 1),
(5716218, 831331, 65234, '<td valign="top">The dog looks content; not so sure about the human.  Processing seems a little too harsh for a contented mood to the image.</td>', 'The dog looks content; not so sure about the human.  Processing seems a little too harsh for a contented mood to the image.', '2009-11-06 09:16:57.000000', NULL, 1),
(5716219, 831291, 65234, '<td valign="top">Beautiful Rottie!  Would like a shallower DOF here, I think, and a tighter crop on the dog''s head with the human in the background but not so much other stuff.</td>', 'Beautiful Rottie!  Would like a shallower DOF here, I think, and a tighter crop on the dog''s head with the human in the background but not so much other stuff.', '2009-11-06 09:21:09.000000', NULL, 1),
(5716221, 831382, 65234, '<td valign="top">They dressed nicely for the fish!  Observation going on everywhere.  Wonder if it confuses the fish to see people underneath them that they can''t get to.</td>', 'They dressed nicely for the fish!  Observation going on everywhere.  Wonder if it confuses the fish to see people underneath them that they can''t get to.', '2009-11-06 09:22:52.000000', NULL, 1),
(5716224, 831102, 65234, '<td valign="top">Poor little guy!  He couldn''t have been too upset since he''s not curled into a ball ;-)</td>', 'Poor little guy!  He couldn''t have been too upset since he''s not curled into a ball ;-)', '2009-11-06 09:23:46.000000', NULL, 1),
(5716261, 830976, 110909, '<td valign="top">reminds me of growning up in west texas.  very emotive shot.  9</td>', 'reminds me of growning up in west texas.  very emotive shot.  9', '2009-11-06 10:43:46.000000', NULL, 1),
(5716262, 831331, 110909, '<td valign="top">love this.  8</td>', 'love this.  8', '2009-11-06 10:45:49.000000', NULL, 1),
(5716264, 831456, 110909, '<td valign="top">impressive catch with the reflection in this doggie''s eye.</td>', 'impressive catch with the reflection in this doggie''s eye.', '2009-11-06 10:46:55.000000', NULL, 1),
(5716265, 830462, 110909, '<td valign="top">this picture makes me so sad, which was probably the point.  the textures and color here are very good and i especially like whatever you''ve done to get the smoothness on the hand.  9</td>', 'this picture makes me so sad, which was probably the point.  the textures and color here are very good and i especially like whatever you''ve done to get the smoothness on the hand.  9', '2009-11-06 10:49:04.000000', NULL, 1),
(5716284, 831393, 109903, '<td valign="top">nice expression on the faces! nice value also.</td>', 'nice expression on the faces! nice value also.', '2009-11-06 11:15:30.000000', NULL, 1),
(5716286, 831422, 109903, '<td valign="top">nice crop...it gets just the important parts and nothing unneeded.</td>', 'nice crop...it gets just the important parts and nothing unneeded.', '2009-11-06 11:17:22.000000', NULL, 1),
(5716292, 831031, 109903, '<td valign="top">nice value and emphasis! well done!</td>', 'nice value and emphasis! well done!', '2009-11-06 11:21:13.000000', NULL, 1),
(5716296, 831438, 27475, '<td valign="top">This is very nice!  Actually I love it!  So lively and great capture!<br/>Gotta love the snow!</td>', 'This is very nice!  Actually I love it!  So lively and great capture!Gotta love the snow!', '2009-11-06 11:34:52.000000', NULL, 1),
(5716297, 831378, 27475, '<td valign="top">good.  but I would have gone with a close crop. but that is me.</td>', 'good.  but I would have gone with a close crop. but that is me.', '2009-11-06 11:35:52.000000', NULL, 1),
(5716300, 831393, 27475, '<td valign="top">Why can''t he hold the cat!!! :)<br/>love it.</td>', 'Why can''t he hold the cat!!! :)love it.', '2009-11-06 11:37:45.000000', NULL, 1),
(5716356, 830082, 65234, '<td valign="top">There''s some similarity in the poses but I think I''d like more emphasis on it ... subjects closer together, shallower DOF ... something.</td>', 'There''s some similarity in the poses but I think I''d like more emphasis on it ... subjects closer together, shallower DOF ... something.', '2009-11-06 12:45:30.000000', NULL, 1),
(5716359, 831250, 65234, '<td valign="top">Awww :-)  I knew there would be pictures of photogenic children and pets in this challenge, and this is a good execution of one.</td>', 'Awww :-)  I knew there would be pictures of photogenic children and pets in this challenge, and this is a good execution of one.', '2009-11-06 12:48:13.000000', NULL, 1),
(5716360, 830281, 65234, '<td valign="top">Pup doesn''t look too happy from what I can see in his body language.  Colors look very washed out on my screen.</td>', 'Pup doesn''t look too happy from what I can see in his body language.  Colors look very washed out on my screen.', '2009-11-06 12:50:31.000000', NULL, 1),
(5716363, 831114, 65234, '<td valign="top">I get it, but feel the point would come across a bit stronger with eye contact from the deer.  The lighting is a bit flat here; maybe could use a boost in contrast or decrease in brightness.</td>', 'I get it, but feel the point would come across a bit stronger with eye contact from the deer.  The lighting is a bit flat here; maybe could use a boost in contrast or decrease in brightness.', '2009-11-06 12:53:32.000000', NULL, 1),
(5716364, 830967, 65234, '<td valign="top">Brave doggie!  Even looks like he''s enjoying it :-)</td>', 'Brave doggie!  Even looks like he''s enjoying it :-)', '2009-11-06 12:53:56.000000', NULL, 1),
(5716365, 831345, 65234, '<td valign="top">LOL!  I''d be shrieking if I saw one that size in my house, too.</td>', 'LOL!  I''d be shrieking if I saw one that size in my house, too.', '2009-11-06 12:54:30.000000', NULL, 1),
(5716369, 830352, 65234, '<td valign="top">Hmmm.  Not sure the perspective is telling the story as effectively as it could, though I''m betting this was a tricky one to try and capture.</td>', 'Hmmm.  Not sure the perspective is telling the story as effectively as it could, though I''m betting this was a tricky one to try and capture.', '2009-11-06 12:57:25.000000', NULL, 1),
(5716370, 831400, 65234, '<td valign="top">That dog is not ergonomically correct; humans shouldn''t have to bend over to pat a dog ;-)  Certainly a  scene I''m very familiar with, though!</td>', 'That dog is not ergonomically correct; humans shouldn''t have to bend over to pat a dog ;-)  Certainly a  scene I''m very familiar with, though!', '2009-11-06 12:59:04.000000', NULL, 1),
(5716372, 831128, 65234, '<td valign="top">Can''t really see the dog''s pose well enough to figure out whether this is a friendly interaction or no interaction at all.  Not quite working for me for this challenge.</td>', 'Can''t really see the dog''s pose well enough to figure out whether this is a friendly interaction or no interaction at all.  Not quite working for me for this challenge.', '2009-11-06 13:00:34.000000', NULL, 1),
(5716374, 830212, 65234, '<td valign="top">Nicely framed by the bridge.</td>', 'Nicely framed by the bridge.', '2009-11-06 13:01:04.000000', NULL, 1),
(5716375, 831371, 65234, '<td valign="top">::smiles:: Great timing on the capture.</td>', '::smiles:: Great timing on the capture.', '2009-11-06 13:01:49.000000', NULL, 1),
(5716376, 830571, 65234, '<td valign="top">Definitely get a sense of interaction from the eye contact.  Bit of a dreamy feel to this.</td>', 'Definitely get a sense of interaction from the eye contact.  Bit of a dreamy feel to this.', '2009-11-06 13:02:39.000000', NULL, 1),
(5716377, 831354, 65234, '<td valign="top">I''m seeing a lot of expression on the dog''s face; the human''s is less clear.  Probably would have gone for B&amp;W on this to minimize some of the background distractions, including the noise.</td>', 'I''m seeing a lot of expression on the dog''s face; the human''s is less clear.  Probably would have gone for B&W on this to minimize some of the background distractions, including the noise.', '2009-11-06 13:05:13.000000', NULL, 1),
(5716379, 831115, 65234, '<td valign="top">Cute capture!  The pigeon looks genuinely helpful ;-)  B&amp;W works well.</td>', 'Cute capture!  The pigeon looks genuinely helpful ;-)  B&W works well.', '2009-11-06 13:05:58.000000', NULL, 1),
(5716526, 830281, 59029, '<td valign="top">yes, subjects are cute, pic meets the challenge.  But a blown-out shot will not do well on this site.</td>', 'yes, subjects are cute, pic meets the challenge.  But a blown-out shot will not do well on this site.', '2009-11-06 15:19:51.000000', NULL, 1),
(5716528, 831438, 59029, '<td valign="top">Great cute shot of doggie in the snow and the ball makes a wonderful focal point.  But though dog is clearly headed for you, you are not in the shot, so hard to tell which way voters may go.</td>', 'Great cute shot of doggie in the snow and the ball makes a wonderful focal point.  But though dog is clearly headed for you, you are not in the shot, so hard to tell which way voters may go.', '2009-11-06 15:21:39.000000', NULL, 1),
(5716689, 831250, 3087, '<td valign="top">Charming portrait, beautifully composed, intimate because of the tight framing, lovely sharp detail, lovely lighting and tones.</td>', 'Charming portrait, beautifully composed, intimate because of the tight framing, lovely sharp detail, lovely lighting and tones.', '2009-11-06 17:30:10.000000', NULL, 1),
(5716690, 831438, 3087, '<td valign="top">I like how this clearly shows human/ animal interaction without a human in the frame - it makes the viewer part of the subject. Cool!</td>', 'I like how this clearly shows human/ animal interaction without a human in the frame - it makes the viewer part of the subject. Cool!', '2009-11-06 17:30:15.000000', NULL, 1),
(5716713, 831242, 103142, '<td valign="top">oh, if only you could have gotten closer or switched to a longer lens! This looks so intriguing, but is just too far away. <br/> <br/>Other things to consider: if you would have taken a shot just a tad later, the light pole wouldn''t be coming up out of the person. Or another option would have been to get down lower for the shot so that perhaps it would be silhouetted. <br/> <br/>Just some thoughts -- feel free to ignore them!</td>', 'oh, if only you could have gotten closer or switched to a longer lens! This looks so intriguing, but is just too far away.  Other things to consider: if you would have taken a shot just a tad later, the light pole wouldn''t be coming up out of the person. Or another option would have been to get down lower for the shot so that perhaps it would be silhouetted.  Just some thoughts -- feel free to ignore them!', '2009-11-06 17:43:52.000000', NULL, 1),
(5716714, 831431, 103142, '<td valign="top">I like the sharpness above, but it seems overprocessed in the water. It might have been better just sharpening the top portion.</td>', 'I like the sharpness above, but it seems overprocessed in the water. It might have been better just sharpening the top portion.', '2009-11-06 17:44:32.000000', NULL, 1),
(5716715, 831393, 103142, '<td valign="top">Absolutely wonderful!! great expressions on both children! -9-</td>', 'Absolutely wonderful!! great expressions on both children! -9-', '2009-11-06 17:45:10.000000', NULL, 1),
(5716718, 830976, 103142, '<td valign="top">It would have been nice if you could have stepped to the left a little and re-shot. The front calf is distracting, but the rest of the shot, especially the cows in the background, is wonderful.</td>', 'It would have been nice if you could have stepped to the left a little and re-shot. The front calf is distracting, but the rest of the shot, especially the cows in the background, is wonderful.', '2009-11-06 17:47:06.000000', NULL, 1),
(5716723, 831369, 103142, '<td valign="top">I love the shot! Clever and funny. One recommendation--the tree is very dark and takes up so much of the photo, it would be nice to get some of the detail back in the tree. I brought it into photoshop (elements) and just did a shadows/highlights on it and lightened the shadows, and I thought the effect was interesting. <br/> <br/>Feel free to ignore this--it was just such a great concept and photo that I had to play with it.  -8-</td>', 'I love the shot! Clever and funny. One recommendation--the tree is very dark and takes up so much of the photo, it would be nice to get some of the detail back in the tree. I brought it into photoshop (elements) and just did a shadows/highlights on it and lightened the shadows, and I thought the effect was interesting.  Feel free to ignore this--it was just such a great concept and photo that I had to play with it.  -8-', '2009-11-06 17:52:26.000000', NULL, 1),
(5716728, 831296, 103142, '<td valign="top">ooh!! Very, veyr nicely done! -8-</td>', 'ooh!! Very, veyr nicely done! -8-', '2009-11-06 17:54:39.000000', NULL, 1),
(5716753, 831250, 60614, '<td valign="top">Now that is the interaction I was expecting to see.  If I ever got off my butt I would have done something similiar but with our Shih Tzu.  Love the choice of B/W tones.  This should be on the front page.  Beautiful. 10</td>', 'Now that is the interaction I was expecting to see.  If I ever got off my butt I would have done something similiar but with our Shih Tzu.  Love the choice of B/W tones.  This should be on the front page.  Beautiful. 10', '2009-11-06 18:30:03.000000', NULL, 1),
(5716761, 831438, 60614, '<td valign="top">All I can say is this looks like the dog is having a great time.  He/She really pops out against the snow and the ball being a different color is perfect. 10</td>', 'All I can say is this looks like the dog is having a great time.  He/She really pops out against the snow and the ball being a different color is perfect. 10', '2009-11-06 18:34:14.000000', NULL, 1),
(5716762, 831393, 60614, '<td valign="top">Someone not happy.  Photo is very emotive.  Nicely done.  Great choice in going with B/W tones. 10</td>', 'Someone not happy.  Photo is very emotive.  Nicely done.  Great choice in going with B/W tones. 10', '2009-11-06 18:34:22.000000', NULL, 1),
(5716764, 830974, 60614, '<td valign="top">I really like the composition and subject choice.  The tones I don''t feel help this photo.  I think more of a B/W tones or a sepia tone would really help in photo.  Wish all the best because I think this is a nice photo. 7</td>', 'I really like the composition and subject choice.  The tones I don''t feel help this photo.  I think more of a B/W tones or a sepia tone would really help in photo.  Wish all the best because I think this is a nice photo. 7', '2009-11-06 18:35:26.000000', NULL, 1),
(5716769, 831267, 60614, '<td valign="top">Like the simplicity of photo.  Blue tones is a nice touch.</td>', 'Like the simplicity of photo.  Blue tones is a nice touch.', '2009-11-06 18:38:43.000000', NULL, 1),
(5716942, 831236, 65234, '<td valign="top">Good doggie!  Personally I''d have a drape on that chair (and pinned partway up the wall behind him) but I am getting obsessive about such things as non-photogenic folding chairs ;-)  The interaction here is very clear, though you probably could do an even closer crop and tell the story with more detail.</td>', 'Good doggie!  Personally I''d have a drape on that chair (and pinned partway up the wall behind him) but I am getting obsessive about such things as non-photogenic folding chairs ;-)  The interaction here is very clear, though you probably could do an even closer crop and tell the story with more detail.', '2009-11-06 20:12:25.000000', NULL, 1),
